==== hedgerow perf-ish checks (heads) ====
--- lod-check ---
// Run with: node fun/hedgerow/tests/lod-check.mjs
// Detail by distance. A soldier switches to his outfit's low-detail mesh
// beyond LOD_FAR and back inside LOD_NEAR (not in between, so he does not
// flicker at the line). Vegetation sorts each tree into full, mid (its
// thinned _mid model) and far (its _lod impostor) by distance, drops what is
// behind the camera, and without a _mid model keeps the old two tiers. And
// detail follows how big things look: down the sights (a narrower view) a
// soldier and the trees keep their full detail further out.
--- distance-check ---
// Run with: node fun/hedgerow/tests/distance-check.mjs
// The land beyond the level (js/distance.js), built with stand-in meshes for
// the nature set's far models: the treeline tiles must face the level, half
// of them mirrored, their bases below the far ground, and none may stand
// between the level and the far buildings (the next village must show).
import './three-hooks.mjs';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
--- fp-check ---
// Run with: node fun/hedgerow/tests/fp-check.mjs
// First person, on the real rig and rifles. While he walks and runs, the
// rifle must sit steady in front of the eyes: the gait's bob and twist are
// steadied out of the upper body (character.js `steady`), so the muzzle
// barely moves in a view that keeps its direction (the mouse's) with the eye
// smoothed as player.js smooths it. Aiming must line the sights up with the
// view: turning the body and bending the spine as player.js does brings the
// front sight onto the middle of the screen. And what the eye sees must make
==== meteora perf-ish checks (heads) ====
--- frame-stats-check ---
// Run with: node tests/frame-stats-check.mjs
// The in-game benchmark (?bench) summarises frame samples with these.
import { test, run, assert, near } from './harness.mjs';
import { createFrameStats } from '../js/frame-stats.js';

test('summarises samples into mean, median, 95th percentile and count', () => {
  const s = createFrameStats();
  for (let i = 1; i <= 100; i++) s.add('frame', i);
--- cull-check ---
// Run with: node tests/cull-check.mjs
// The belt is drawn from per-frame visible lists; this pins that the lists
// hold exactly the rocks a camera can see, at the right level of detail.
import { test, run, assert } from './harness.mjs';
import { createCuller } from '../js/cull.js';
import { createField } from '../js/field.js';
import { FIELD } from '../js/config.js';

--- resolution-check ---
// Run with: node tests/resolution-check.mjs
// Adaptive resolution: drop a level when frames run long, climb back when the
// display's refresh rate holds, and never retry a level that just failed.
import { test, run, assert } from './harness.mjs';
import { createResolution } from '../js/resolution.js';

const feed = (r, ms, seconds) => { let ratio = r.ratio; for (let t = 0; t < seconds; t += ms / 1000) ratio = r.frame(ms); return ratio; };

--- harness ---
/* A twenty-line test runner, so the checks need nothing beyond Node. Each
   check file registers cases with `test`, then awaits `run`, which prints
   one line per case and exits non-zero when any of them failed. */
import assert from 'node:assert/strict';

