import { createRetro } from '../js/retro.js';
==== tyran frame-cost / effects-render-work heads ====
--- frame-cost-check ---
// Frame-cost harness: the seeded 18-ship flight from performance-check.mjs, measured
// two ways so a renderer change can be compared on any machine, including one whose
// only GPU is a software renderer. Numbers are measurements, not pass/fail thresholds;
// coverage and page errors are asserted.
//   TYRAN_FRAME_MODE=js   replaces WebGL2 with a no-op context: main-thread JavaScript only.
//   TYRAN_FRAME_MODE=gpu  runs the real renderer and sums the analytic fill area of every triangle.
--- effects-render-work-check ---
// Serve repo root, then REDACTED.mjs node this file.
// Compare cropped streaks with their complete source image and preserve edge optics.
import assert from 'node:assert/strict';

const { chromium } = await import(process.env.TYRAN_PLAYWRIGHT || 'playwright');
const browser = await chromium.launch({ channel: process.env.TYRAN_BROWSER || 'chrome', headless: true });
--- gpu-batch-check ---
import assert from 'node:assert/strict';
import {GPUCanvas2D} from '../gpu-canvas.js';
import {mockCanvas} from './gpu-mock.mjs';

const image=(name,width=32,height=32)=>({name,width,height,_tyranTextureVersion:1});
function renderer(){const surface=mockCanvas();return {surface,c:new GPUCanvas2D(surface.width,surface.height,surface)};}
==== ashline performance.test / benchmark heads ====
--- performance.test ---
import test from 'node:test';
import assert from 'node:assert/strict';
import * as sim from '../sim.js';
import {encodeGame,decodeGame} from '../save.js';
import {performanceScene} from './performance-scenes.mjs';
const snapshot=s=>JSON.parse(encodeGame(s)).game;
--- performance-benchmark ---
// node tests/performance-benchmark.mjs; optional ASHLINE_PROFILE=/tmp/sim.cpuprofile.
// ASHLINE_SIM_URL=file:///…/sim.js benchmarks another simulation. sim.js imports its sibling modules
// (ai.js, terrain.js, flocking.js, traffic.js, mission.js, campaign.js, abilities.js), so point it into a
// complete candidate checkout.
// Report timing, never assert machine-specific wall-clock thresholds.
import {performance} from 'node:perf_hooks';
