      const m = new Float32Array(W * H * 4);
      renderer.readRenderTargetPixels(meter, 0, 0, W, H, m);
      const order = Array.from({ length: W * H }, (_, i) => i);
      order.sort((x, y) => m[x * 4] - m[y * 4]);
      const weight = (i) => Math.floor(i / W) < HALF_ROWS ? 0.5 : 1;
