      return Promise.resolve({ factor: s[0], target: s[1], metered, has: s[3], median, exposure: base * s[0] });
    },
    get metered() { return metered; },
    get factor() { return factor; },
    set factor(v) { factor = v; stateMat.uniforms.uReset.value = 1; stateMat.uniforms.uResetFactor.value = v; },     // (checks: start from a given exposure)
  };
}

