// Headless Hedgerow exposure trace + readback-stall measurement.
// usage: node trace.mjs <label> <seconds> <out.json> [--nosample]
// Serves the worktree through page.route (no server process), boots the mission with the real
// GPU (Chrome for Testing, ANGLE Metal), stands at the spawn, launches a flare at 10 s, samples
// the adaptation every 100 ms (unless --nosample) and records every getBufferSubData duration
// and every animation-frame interval.
import { chromium } from '/Users/vojta/.REDACTED.mjs';
import { readFile } from 'node:fs/promises';
import { writeFileSync } from 'node:fs';
import path from 'node:path';

const WT = 'REDACTED';
const EXE = 'REDACTED Chrome for Testing.app/Contents/MacOS/Google Chrome for Testing';
const args = process.argv.slice(2);
const noSample = args.includes('--nosample');
const [label = 'run', secondsArg = '30', out = 'trace.json'] = args.filter(a => !a.startsWith('--'));
const seconds = Number(secondsArg);
const MIME = { html: 'text/html', js: 'text/javascript', mjs: 'text/javascript', css: 'text/css', json: 'application/json', glb: 'model/gltf-binary', gltf: 'model/gltf+json', png: 'image/png', jpg: 'image/jpeg', jpeg: 'image/jpeg', webp: 'image/webp', svg: 'image/svg+xml', woff2: 'font/woff2', woff: 'font/woff', mp3: 'audio/mpeg', ogg: 'audio/ogg', wav: 'audio/wav', bin: 'application/octet-stream', ktx2: 'image/ktx2', txt: 'text/plain' };

const browser = await chromium.launch({ executablePath: EXE, headless: true, args: ['--use-angle=metal', '--enable-gpu', '--ignore-gpu-blocklist'] });
try {
  const context = await browser.newContext({ viewport: { width: 1280, height: 720 }, deviceScaleFactor: 1 });
  const page = await context.newPage();
  await page.route('http://127.0.0.1:8703/**', async (route) => {
    const u = new URL(route.request().url());
    let p = decodeURIComponent(u.pathname);
    if (p.endsWith('/')) p += 'index.html';
    try {
      const body = await readFile(path.join(WT, p));
      const ext = p.split('.').pop().toLowerCase();
      await route.fulfill({ status: 200, body, headers: { 'content-type': MIME[ext] || 'application/octet-stream', 'cache-control': 'no-store' } });
    } catch { await route.fulfill({ status: 404, body: 'not found' }); }
  });
  const errors = [], logs = [];
  page.on('pageerror', e => errors.push(String(e.message).slice(0, 300)));
  const known = /AudioContext was not allowed|Trying to use 16 texture units/;
  page.on('console', m => { if ((m.type() === 'error' || m.type() === 'warning') && !known.test(m.text())) logs.push(m.type() + ': ' + m.text().slice(0, 400)); });
  await page.addInitScript(() => {
    const S = window.__stalls = { calls: 0, durations: [], frames: [] };
    const proto = WebGL2RenderingContext.prototype, orig = proto.getBufferSubData;
    proto.getBufferSubData = function (...a) { const t = performance.now(); const r = orig.apply(this, a); S.durations.push(performance.now() - t); S.calls++; return r; };
    const raf = window.requestAnimationFrame.bind(window); let last = 0;
    window.requestAnimationFrame = (fn) => raf((ts) => { if (last) S.frames.push(ts - last); last = ts; fn(ts); });
  });
  const boot0 = Date.now();
  await page.goto('http://127.0.0.1:8703/fun/hedgerow/index.html?debug&go&god', { waitUntil: 'domcontentloaded' });
  await page.waitForSelector('[data-loading]', { state: 'hidden', timeout: 180000 });
  await page.click('[data-action="start"]');
  await page.waitForFunction(() => window.hedgerow?.G?.time > 0.5, null, { timeout: 60000 });
  const bootMs = Date.now() - boot0;
  // settle two seconds, then measure from a clean slate
  await page.waitForTimeout(2000);
  await page.evaluate(() => { const S = window.__stalls; S.calls = 0; S.durations.length = 0; S.frames.length = 0; });
  const t0 = Date.now(); const samples = []; let flared = false;
  while (Date.now() - t0 < seconds * 1000) {
    const wall = (Date.now() - t0) / 1000;
    if (!noSample) {
      const s = await page.evaluate(async () => {
        const G = hedgerow.G, a = hedgerow.fx.adapt;
        let r = { factor: a.factor, metered: a.metered };
        if (typeof a.read === 'function') r = await a.read();
        return { t: G.time, exposure: G.renderer.toneMappingExposure, ...r, burning: G.flares.burning };
      });
      s.wall = wall; samples.push(s);
    }
    if (!flared && wall >= 10) { flared = true; await page.evaluate(() => hedgerow.G.flares.launchNow(hedgerow.G.camera.position)); }
    await page.waitForTimeout(100);
  }
  const S = await page.evaluate(() => window.__stalls);
  const q = (arr, p) => { if (!arr.length) return null; const s = [...arr].sort((a, b) => a - b); return +s[Math.min(s.length - 1, Math.floor(p * s.length))].toFixed(2); };
  const over5 = S.durations.filter(d => d > 5);
