// Boot Alpen headlessly from a worktree: does the terrain worker load, and are there errors?
import { chromium } from '/Users/vojta/.REDACTED.mjs';
import { readFile } from 'node:fs/promises';
import path from 'node:path';
const WT = process.env.ALPEN_WT;
const EXE = 'REDACTED Chrome for Testing.app/Contents/MacOS/Google Chrome for Testing';
const MIME = { html: 'text/html', js: 'text/javascript', mjs: 'text/javascript', css: 'text/css', json: 'application/json', glb: 'model/gltf-binary', gltf: 'model/gltf+json', png: 'image/png', jpg: 'image/jpeg', webp: 'image/webp', svg: 'image/svg+xml', woff2: 'font/woff2', mp3: 'audio/mpeg', ogg: 'audio/ogg', wav: 'audio/wav', bin: 'application/octet-stream' };
const browser = await chromium.launch({ executablePath: EXE, headless: true, args: ['--use-angle=metal', '--enable-gpu', '--ignore-gpu-blocklist'] });
try {
  const page = await (await browser.newContext({ viewport: { width: 1280, height: 720 } })).newPage();
  const served = new Set();
  await page.route('http://127.0.0.1:8701/**', async (route) => {
    let p = decodeURIComponent(new URL(route.request().url()).pathname); if (p.endsWith('/')) p += 'index.html';
    try { const body = await readFile(path.join(WT, p)); served.add(p); await route.fulfill({ status: 200, body, headers: { 'content-type': MIME[p.split('.').pop().toLowerCase()] || 'application/octet-stream' } }); }
    catch { await route.fulfill({ status: 404, body: 'nf' }); }
  });
  const errors = [], logs = [];
  page.on('pageerror', e => errors.push(String(e.message).slice(0, 300)));
  page.on('console', m => { if (m.type() === 'error' || m.type() === 'warning') logs.push(m.type() + ': ' + m.text().slice(0, 300)); });
  page.on('worker', w => logs.push('worker started: ' + w.url().split('/').pop()));
  await page.addInitScript(() => { const S = window.__frames = []; const raf = window.requestAnimationFrame.bind(window); let last = 0; window.requestAnimationFrame = (fn) => raf((ts) => { if (last) S.push(ts - last); last = ts; fn(ts); }); });
  await page.goto('http://127.0.0.1:8701/fun/alpen/', { waitUntil: 'domcontentloaded' });
  await page.waitForTimeout(25000);
  const frames = await page.evaluate(() => window.__frames.slice(-600));
  const q = (arr, p) => { if (!arr.length) return null; const s = [...arr].sort((a, b) => a - b); return +s[Math.min(s.length - 1, Math.floor(p * s.length))].toFixed(2); };
  console.log(JSON.stringify({ workerServed: [...served].filter(p => p.includes('worker')), workers: page.workers().map(w => w.url().split('/').pop()), frames: { n: frames.length, median: q(frames, 0.5), p95: q(frames, 0.95), max: +Math.max(0, ...frames).toFixed(1) }, errors, logs: logs.slice(0, 15) }, null, 1));
} finally { await browser.close(); }

